"""Publish model and editor references from verified browser captures."""
import json,shutil,html
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'arte/muebles-v19';CAP=ROOT.parent/'Muebles_v19'
data=json.loads((ROOT/'src/furniture-components.json').read_text(encoding='utf8'))
models=['librero_isla','hide_HB13','hide_HB06','hide_HB10','hide_HB03','drawer_standard','book_standard','mesa_comedor','am_B06','am_B10','am_A11','am_herbolario','cama_A10','am_cama_nino','prop_cuna']
screens=['editor-comedor','editor-biblioteca','editor-colocacion-invalida','editor-librero-girado','editor-escondite','editor-iphone','editor-iphone-horizontal','biblioteca_v16','abuela','infantil','despensa','cuna']
for name in models+screens:shutil.copy2(CAP/(name+'.png'),OUT/(name+'.png'))
reports={}
for name,file in [('models','furniture_validation.json'),('editor','editor_validation.json'),('editorMobile','editor_mobile_validation.json'),('browser','browser_validation.json'),('iphone12Emulated','iphone12_validation.json'),('online','online_validation.json'),('observer','editor_observer_validation.json'),('render','render_validation.json')]:reports[name]=json.loads((CAP/file).read_text(encoding='utf8'))
reports['sessions']=json.loads((ROOT/'test-results/session-casona.json').read_text(encoding='utf8'))
(OUT/'verificacion.json').write_text(json.dumps(reports,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
style='''*{box-sizing:border-box}body{margin:0;background:#eee8dc;color:#293d36;font:16px/1.5 system-ui}main{max-width:1400px;margin:auto;padding:24px}h1{font:600 32px Georgia}h2{font:600 24px Georgia}a{color:#31715d}nav{display:flex;gap:18px;flex-wrap:wrap}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(290px,1fr));gap:16px}figure{margin:0;background:#faf7eb;border-radius:12px;overflow:hidden}img{display:block;width:100%}figcaption{padding:10px}.models{grid-template-columns:repeat(4,minmax(0,1fr))}.crop{aspect-ratio:990/650;overflow:hidden;background:#a5aaa7}.crop img{width:100%;height:auto}section{padding:24px 0;border-bottom:1px solid #b7af9b}.note{color:#63766a;max-width:950px}@media(max-width:750px){.models{grid-template-columns:repeat(2,minmax(0,1fr))}main{padding:14px}}'''
cards=''.join(f'<figure><a href="{id}.png"><div class="crop"><img src="{id}.png" alt="{html.escape(data["tools"][id]["name"])}"></div></a><figcaption>{html.escape(data["tools"][id]["name"])}</figcaption></figure>'for id in models)
header='<nav><a href="../../editor/">Decorar la casona</a><a href="./">Editar modelos</a><a href="../../docs/editor-v19.md">Cómo usar el editor</a><a href="../../juego/">Jugar</a><a href="verificacion.json">Verificación</a></nav>'
(OUT/'resumen.html').write_text('<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Muebles de la casona · V19</title><style>'+style+'</style><main><small>NOCHE DE ÁNIMAS · MOBILIARIO V19</small><h1>Muebles de la casona</h1><p>Libreros, roperos, mesas y camas · apoyos y funciones conservados · componentes editables</p><div class="grid models">'+cards+'</div></main></html>',encoding='utf8')
gallery=''.join(f'<figure><a href="{name}.png"><img loading="lazy" src="{name}.png" alt="{label}"></a><figcaption>{label}</figcaption></figure>'for name,label in [('editor-comedor','Modo de decoración: selecciona y mueve en 3D'),('editor-biblioteca','Biblioteca con libros independientes'),('editor-colocacion-invalida','Vista previa roja: una colocación inválida se cancela'),('editor-librero-girado','Giro del librero conservando sus libros'),('editor-escondite','El escondite se mueve junto con su entrada'),('abuela','Cama, mesa y adornos dentro de la partida'),('infantil','Recámara infantil'),('cuna','Cuna con base, patas y barrotes unidos'),('biblioteca_v16','Librero dentro del juego'),('despensa','Estantes con sus contenidos'),('editor-iphone','Editor táctil: iPhone 12 emulado'),('editor-iphone-horizontal','Editor táctil horizontal')])
(OUT/'referencias.html').write_text('<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Referencias de muebles y editor V19</title><style>'+style+'</style><main><h1>Muebles y modo de decoración</h1>'+header+'<p class="note">Los modelos nuevos conservan sus huellas y superficies, 24 posibles escondites, 24 libros independientes, 66 cajones activos y los adornos arrojables. La vista del editor simplifica la estructura para mostrar el interior; las capturas del juego conservan la iluminación nocturna.</p><p><a href="resumen.html">Ver los modelos</a> · <a href="../../docs/muebles-v19.md">Especificación de componentes</a></p><div class="grid">'+gallery+'</div><h2>Cómo empezar</h2><ol><li>Abre Abrir editor.cmd en tu proyecto.</li><li>Elige piso y cuarto.</li><li>Selecciona una pieza y arrástrala, o pulsa Mover y toca el destino.</li><li>Gira, coloca en verde y pulsa Aplicar al juego local.</li><li>Pulsa Probar cambios locales. En la web, descarga el plano para compartirlo.</li></ol><p class="note">Las pruebas móviles son emuladas; no se afirma una medición de FPS en un teléfono físico.</p></main></html>',encoding='utf8')
print('Published furniture models, decoration-mode guide, captures and verification.')
